/* block
   comment */

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source = "hashicorp/random"
    }
  }
  backend "s3" {
    bucket = "tfstate"
  }
}

provider "aws" {
  region = var.region
  alias  = "west"
}

variable "region" {
  type        = string
  default     = "us-east-1"
  description = "The region"
}

variable "count_num" {
  type = number
}

locals {
  name   = "app-${var.region}"
  tags   = { Env = "prod" }
  nested = local.name
}

resource "aws_s3_bucket" "my_bucket" {
  bucket = "my-bucket-name"
  tags   = local.tags
}

resource "aws_instance" "web" {
  ami           = data.aws_ami.ubuntu.id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.main.id
  depends_on    = [aws_s3_bucket.my_bucket]
}

data "aws_ami" "ubuntu" {
  most_recent = true
  filter {
    name   = "name"
    values = ["ubuntu/*"]
  }
}

data "aws_caller_identity" "current" {}

output "bucket_arn" {
  value       = aws_s3_bucket.my_bucket.arn
  description = "ARN"
  sensitive   = false
}

output "ami_id" {
  value = data.aws_ami.ubuntu.id
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "5.0.0"
  name    = var.region
}

check "health" {
  assert {
    condition = true
  }
}

moved_thing = aws_s3_bucket.my_bucket.id
EOF
